<?php require_once __DIR__.'/auth.php';require_admin();require_once __DIR__.'/../includes/admin_layout.php';$pdo=db();$today=date('Y-m-d');$stats=['today_visits'=>(int)$pdo->query("SELECT COUNT(*) FROM visits WHERE DATE(visit_date)='$today'")->fetchColumn(),'today_appointments'=>(int)$pdo->query("SELECT COUNT(*) FROM appointments WHERE appointment_date='$today'")->fetchColumn(),'active_admissions'=>(int)$pdo->query("SELECT COUNT(*) FROM admissions WHERE status='Admitted'")->fetchColumn(),'completed_labs'=>(int)$pdo->query("SELECT COUNT(*) FROM lab_orders WHERE status='Completed'")->fetchColumn(),'revenue'=>(float)$pdo->query("SELECT COALESCE(SUM(amount),0) FROM payments WHERE DATE(paid_at)='$today'")->fetchColumn()];$recent=$pdo->query('SELECT DATE(visit_date) d,COUNT(*) n FROM visits GROUP BY DATE(visit_date) ORDER BY d DESC LIMIT 14')->fetchAll();admin_header('Reports','reports.php');?><div class="pagehead"><div><h1>Reports</h1><div class="muted">Operational snapshot for Access Hospital.</div></div></div><div class="grid"><div class="card stat"><span class="muted">Visits today</span><span class="n"><?=$stats['today_visits']?></span></div><div class="card stat"><span class="muted">Appointments today</span><span class="n"><?=$stats['today_appointments']?></span></div><div class="card stat"><span class="muted">Active admissions</span><span class="n"><?=$stats['active_admissions']?></span></div><div class="card stat"><span class="muted">Completed lab orders</span><span class="n"><?=$stats['completed_labs']?></span></div><div class="card stat"><span class="muted">Payments today</span><span class="n">UGX <?=number_format($stats['revenue'],0)?></span></div></div><div class="card" style="margin-top:18px"><h2>Recent daily visits</h2><table class="table"><tr><th>Date</th><th>Visits</th></tr><?php foreach($recent as $r):?><tr><td><?=e($r['d'])?></td><td><?=e($r['n'])?></td></tr><?php endforeach;?></table></div><?php admin_footer();
